<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {request} from './service';
const rows=ref<any[]>([]),query=ref(''),season=ref('all'),loading=ref(true),notice=ref(''),saving=ref('');
const page=ref(1),total=ref(0),availableSeasons=ref<string[]>([]);
const current=`${new Date().getFullYear()}-Q${Math.floor(new Date().getMonth()/3)+1}`;
const seasons=computed(()=>[...new Set([current,...availableSeasons.value])].sort().reverse());
const filtered=computed(()=>rows.value);
async function load(){loading.value=true;try{const state=await request('/api/private/catalog/records/library?subtype='+encodeURIComponent('番剧')+'&pageSize=24&page='+page.value+'&season='+encodeURIComponent(season.value)+'&q='+encodeURIComponent(query.value));rows.value=state.items.map((x:any)=>({season:'',broadcast:'',public:false,...x}));total.value=state.total;availableSeasons.value=state.seasons;}catch(e:any){notice.value=e.message;}finally{loading.value=false;}}
async function save(item:any){saving.value=item.id;try{Object.assign(item,await request('/api/private/records/library/'+item.id,'PUT',item));await load();notice.value='已保存。公开封面允许访客访问，私人感想与进度不会公开。';}catch(e:any){notice.value=e.message;}finally{saving.value='';}}
function fallback(e:any){if(!e.target.src.endsWith('/assets/flower-03.webp'))e.target.src='/assets/flower-03.webp';}
let searchTimer;watch([query,season],()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;load();},250);});onMounted(load);
</script>
<template><section class="anime-wall"><header><span class="space-eyebrow">COLLECTION / PUBLIC SCREENING</span><h1>季度番剧海报墙</h1><p>采集确认后自动加入兴趣收藏。在这里整理季度，选择公开展示的作品。采集作品是否自动公开由“页面与片头”的总开关决定，个人进度与笔记始终私有。</p><nav><RouterLink to="/automation">采集新番 ↗</RouterLink><RouterLink to="/life/library">兴趣收藏 ↗</RouterLink><a href="/anime" target="_blank" rel="noopener">公开放映室 ↗</a></nav></header><div class="wall-tools"><el-input v-model="query" clearable placeholder="搜索番名或标签" aria-label="搜索番剧"/><el-select v-model="season" aria-label="筛选季度"><el-option label="全部季度" value="all"/><el-option v-for="q in seasons" :key="q" :label="q" :value="q"/><el-option label="待整理" value=""/></el-select><span>共 {{total}} 部 · 本页 {{rows.filter(x=>x.effectivePublic).length}} 部公开</span></div><p v-if="notice" role="status">{{notice}}</p><p v-if="loading" class="wall-empty">正在整理海报…</p><div v-else class="poster-grid"><article v-for="item in filtered" :key="item.id"><div class="poster-art"><img :src="item.cover" :alt="item.title" loading="lazy" @error="fallback"/><span>{{item.effectivePublic?'博客公开':'私人收藏'}}</span></div><div class="poster-details"><h2>{{item.title}}</h2><label>归属季度<el-input v-model="item.season" placeholder="2026-Q4" maxlength="7"/></label><label>播出时间<el-input v-model="item.broadcast" placeholder="例如：每周四 / 10月开播" maxlength="100"/></label><div class="poster-actions"><el-switch v-model="item.public" active-text="单独公开"/><el-button type="primary" :loading="saving===item.id" @click="save(item)">保存</el-button></div></div></article></div><el-pagination v-if="total>24" v-model:current-page="page" :total="total" :page-size="24" layout="prev, pager, next" @current-change="load"/><div v-if="!loading&&!filtered.length" class="wall-empty"><h2>还没有这一季的海报。</h2><p>去自动化采集并确认保存，或在兴趣收藏中手动添加番剧。</p><el-button @click="load">重新读取</el-button></div></section></template>
<style scoped>
.anime-wall{max-width:1240px;margin:auto}h1{font-size:30px;margin:12px 0}header p,.wall-empty,.wall-tools>span{font-size:12px;line-height:1.8;color:var(--studio-muted)}nav{display:flex;gap:20px;font-size:12px;margin-top:20px}.wall-tools{display:flex;gap:14px;align-items:center;margin:28px 0}.wall-tools .el-input{max-width:320px}.wall-tools .el-select{width:160px}.wall-tools>span{margin-left:auto}.poster-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:22px}.poster-grid article{overflow:hidden;border:1px solid var(--studio-line);border-radius:12px;background:var(--studio-panel)}.poster-art{position:relative;aspect-ratio:3/4;overflow:hidden;background:var(--studio-bg)}.poster-art img{width:100%;height:100%;object-fit:cover;transition:transform .4s}.poster-art:hover img{transform:scale(1.035)}.poster-art span{position:absolute;top:14px;left:14px;background:#212030c9;color:white;padding:6px 10px;border-radius:20px;font-size:11px}.poster-details{padding:18px}.poster-details h2{font-size:17px;margin:0 0 18px;line-height:1.5}.poster-details label{display:grid;gap:7px;font-size:11px;color:var(--studio-muted);margin:12px 0}.poster-actions{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:18px}.wall-empty{text-align:center;padding:70px 20px}@media(max-width:650px){.wall-tools{flex-wrap:wrap}.poster-grid{grid-template-columns:1fr}.wall-tools>span{margin-left:0}}@media(prefers-reduced-motion:reduce){.poster-art img{transition:none}}
</style>
